// CPU-projected rendering of the same licensed 3D geometry for WebGL-disabled browsers.
// This renderer does not synthesize market values or neural activity.
import * as THREE from './vendor/three.module.js';
export class SoftwareRenderer{
 constructor({canvas}){this.domElement=canvas;this.isSoftware=true;this.context=canvas.getContext('2d',{alpha:true});if(!this.context)throw Error('Canvas unavailable');this.ratio=1;this.width=1;this.height=1;this.theme='dark';this.createSprites();}
 setTheme(theme){if(this.theme===theme)return;this.theme=theme;this.createSprites();}
 createSprites(){this.sprites=[];for(let i=0;i<16;i++){const c=document.createElement('canvas');c.width=c.height=48;const ctx=c.getContext('2d'),v=i/15,[r,g,b]=this.palette(v),gradient=ctx.createRadialGradient(24,24,1,24,24,24);gradient.addColorStop(0,`rgba(${r},${g},${b},1)`);gradient.addColorStop(.18,`rgba(${r},${g},${b},1)`);gradient.addColorStop(.28,`rgba(${r},${g},${b},.18)`);gradient.addColorStop(.7,`rgba(${r},${g},${b},.025)`);gradient.addColorStop(1,`rgba(${r},${g},${b},0)`);ctx.fillStyle=gradient;ctx.fillRect(0,0,48,48);this.sprites.push(c);}}
 setPixelRatio(r){this.ratio=Math.min(r,1.25)}getPixelRatio(){return this.ratio}setSize(w,h){this.width=w;this.height=h;this.domElement.width=Math.round(w*this.ratio);this.domElement.height=Math.round(h*this.ratio);this.domElement.style.width=w+'px';this.domElement.style.height=h+'px';}setAnimationLoop(fn){const loop=()=>{fn();this.animation=requestAnimationFrame(loop)};this.animation=requestAnimationFrame(loop)}
 palette(v){if(this.theme==='light'){let a,b,t;if(v<.35){a=[38,64,102];b=[31,64,217];t=v/.35}else if(v<.7){a=[77,38,199];b=[199,20,56];t=(v-.35)/.35}else{a=[204,26,20];b=[179,92,5];t=(v-.7)/.3}return a.map((n,i)=>Math.round(n+(b[i]-n)*t));}let a,b,t;if(v<.35){a=[10,25,40];b=[40,65,255];t=v/.35}else if(v<.7){a=[65,45,255];b=[255,35,45];t=(v-.35)/.35}else{a=[255,45,20];b=[255,243,90];t=(v-.7)/.3}return a.map((n,i)=>Math.round(n+(b[i]-n)*t));}
 render(scene,camera){const c=this.context,w=this.width,h=this.height;c.setTransform(this.ratio,0,0,this.ratio,0,0);c.clearRect(0,0,w,h);scene.updateMatrixWorld(true);camera.updateMatrixWorld();camera.matrixWorldInverse.copy(camera.matrixWorld).invert();const vp=new THREE.Matrix4().multiplyMatrices(camera.projectionMatrix,camera.matrixWorldInverse),faces=[],lines=[],points=[];const light=new THREE.Vector3(-.35,.8,.5).normalize();const normalMatrix=new THREE.Matrix3(),normal=new THREE.Vector3(),vector=new THREE.Vector3(),color=new THREE.Color();
 const project=(x,y,z,m)=>{vector.set(x,y,z).applyMatrix4(m).applyMatrix4(vp);return[(vector.x*.5+.5)*w,(-vector.y*.5+.5)*h,vector.z]};
 scene.traverse(o=>{if(!o.geometry||!o.material||!o.visible)return;let parent=o.parent;while(parent){if(!parent.visible)return;parent=parent.parent}const g=o.geometry,pa=g.attributes.position;if(!pa)return;const mat=Array.isArray(o.material)?o.material[0]:o.material;if(!mat||mat.visible===false||mat.opacity===0)return;const a=pa.array,projected=new Array(pa.count);for(let i=0;i<pa.count;i++)projected[i]=project(a[i*3],a[i*3+1],a[i*3+2],o.matrixWorld);
 if(o.isPoints){const values=g.attributes.activation?.array;if(!values)return;const scale=mat.uniforms?.uScale?.value||1;for(let i=0;i<projected.length;i++){const p=projected[i];if(p[2]<-1||p[2]>1)continue;const v=Math.min(1,Math.abs(values[i])/scale);points.push({p,v,scale:mat.uniforms?.uViewScale?.value||1});}return;}
 if(o.isLineSegments){const colors=g.attributes.color?.array;for(let i=0;i+1<projected.length;i+=2){const a=projected[i],b=projected[i+1];if(a[2]<-1||a[2]>1||b[2]<-1||b[2]>1)continue;const bucket=colors?Math.min(7,Math.floor((colors[i*3]||0)*8)):-1;lines.push({a,b,bucket,color:mat.color?.getStyle()||'#3b5537',opacity:mat.opacity??1});}return;}
 if(!o.isMesh)return;normalMatrix.getNormalMatrix(o.matrixWorld);const na=g.attributes.normal?.array,indices=g.index?.array,triangles=indices?indices.length/3:pa.count/3;const base=mat.color||color.setHex(0xb4a476);for(let t=0;t<triangles;t++){const ia=indices?indices[t*3]:t*3,ib=indices?indices[t*3+1]:t*3+1,ic=indices?indices[t*3+2]:t*3+2;const p=projected[ia],q=projected[ib],r=projected[ic];if(!p||!q||!r||p[2]<-1||p[2]>1||q[2]<-1||q[2]>1||r[2]<-1||r[2]>1)continue;if(Math.max(p[0],q[0],r[0])<0||Math.min(p[0],q[0],r[0])>w||Math.max(p[1],q[1],r[1])<0||Math.min(p[1],q[1],r[1])>h)continue;let shade=1;if(na){normal.set(na[ia*3],na[ia*3+1],na[ia*3+2]).applyMatrix3(normalMatrix).normalize();shade=.62+.48*Math.abs(normal.dot(light));}const R=Math.min(255,Math.round(Math.pow(base.r,1/2.2)*255*shade)),G=Math.min(255,Math.round(Math.pow(base.g,1/2.2)*255*shade)),B=Math.min(255,Math.round(Math.pow(base.b,1/2.2)*255*shade));faces.push({p,q,r,z:(p[2]+q[2]+r[2])/3,style:`rgba(${R},${G},${B},${mat.opacity??1})`});}
 });
 faces.sort((a,b)=>b.z-a.z);for(const f of faces){c.fillStyle=f.style;c.beginPath();c.moveTo(f.p[0],f.p[1]);c.lineTo(f.q[0],f.q[1]);c.lineTo(f.r[0],f.r[1]);c.closePath();c.fill();if(f.style.endsWith(',1)')){c.strokeStyle=f.style;c.lineWidth=.45;c.stroke();}}
 const buckets=new Map();for(const line of lines){const key=line.bucket>=0?'brain'+line.bucket:line.color;if(!buckets.has(key))buckets.set(key,[]);buckets.get(key).push(line)}for(const [key,group]of buckets){const b=group[0].bucket;c.strokeStyle=b>=0?`rgba(${60+b*24},${55+b*9},${180-b*15},.24)`:group[0].color;c.globalAlpha=b>=0?1:group[0].opacity;c.lineWidth=b>=0?.7:1;c.beginPath();for(const l of group){c.moveTo(l.a[0],l.a[1]);c.lineTo(l.b[0],l.b[1]);}c.stroke();}c.globalAlpha=1;
 for(const {p,v,scale}of points){const radius=(2+v*4)*scale;c.drawImage(this.sprites[Math.round(v*15)],p[0]-radius,p[1]-radius,radius*2,radius*2);const rgb=this.palette(v);c.fillStyle=`rgb(${rgb[0]},${rgb[1]},${rgb[2]})`;c.beginPath();c.arc(p[0],p[1],(.9+v*.7)*scale,0,Math.PI*2);c.fill();}
 }
}
